@section('scripts')@if($itinerarios->isNotEmpty())<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const routes=@json($itinerarios->map(fn($item)=>collect($item['tramos'])->flatMap(fn($bus)=>[$bus->origenMunicipio,$bus->destinoMunicipio])->unique('id')->values()));const map=L.map('route-map');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);const points=[];routes.forEach(route=>route.forEach(m=>{if(m.latitud!==null&&m.longitud!==null){const point=[Number(m.latitud),Number(m.longitud)];points.push(point);L.marker(point).addTo(map).bindPopup(m.nombre);}}));routes.forEach(route=>{const line=route.filter(m=>m.latitud!==null&&m.longitud!==null).map(m=>[Number(m.latitud),Number(m.longitud)]);if(line.length>1)L.polyline(line,{color:'#0d6efd'}).addTo(map);});if(points.length)map.fitBounds(points,{padding:[30,30]});else map.setView([12.8654,-85.2072],7);</script>@endif@endsection
